<template>
  <FmStatePanel v-if="!adminSession.ready" state="loading" title="正在打开管理后台"/>
  <div v-else-if="!adminSession.user" class="admin-auth">
    <section class="admin-auth-copy"><div class="admin-symbol">R</div><span class="fm-kicker">SYSTEM ADMINISTRATION</span><h1>系统管理中心</h1><p>这里用于全站运维、用户管理、运行监控和系统设置，与普通用户工作台完全分离。</p><div class="admin-auth-points"><span>独立管理员会话</span><span>全站聚合监控</span><span>敏感设置集中管理</span></div></section>
    <form class="admin-login fm-card" @submit.prevent="login"><span class="fm-kicker">仅限系统管理员</span><h2>登录管理后台</h2><label class="field"><span>管理员账号</span><input v-model.trim="credentials.email" autocomplete="username" required autofocus/></label><label class="field"><span>管理员密码</span><input v-model="credentials.password" type="password" autocomplete="current-password" required/></label><div v-if="loginError" class="notice error">{{loginError}}</div><FmButton variant="primary" type="submit" :loading="loginBusy">管理员登录</FmButton><RouterLink to="/" class="return-link">返回用户工作台</RouterLink></form>
  </div>
  <div v-else class="admin-shell">
    <aside><div class="admin-brand"><span>R</span><div>RateWatch<small>系统管理中心</small></div></div><nav><button v-for="item in nav" :key="item.value" :class="{active:tab===item.value}" @click="tab=item.value"><component :is="item.icon" :size="17" :stroke-width="1.8" aria-hidden="true"/>{{item.label}}</button></nav><div class="admin-account"><span>{{adminSession.user.email}}</span><button @click="logout"><LogOut :size="14" aria-hidden="true"/>退出管理后台</button></div></aside>
    <main>
      <template v-if="tab==='overview'">
        <header class="admin-head"><div><span class="fm-kicker">全站运行状态</span><h1>运维数据中心</h1><p>所有指标均由数据库聚合生成，不加载租户明细请求。</p></div><div class="fm-actions"><FmButton variant="outline" :loading="loading" @click="loadAll">刷新数据</FmButton><FmButton variant="primary" :loading="demoBusy" @click="createDemo">生成演示数据</FmButton></div></header>
        <div class="fm-stats"><article class="fm-stat"><span class="label">注册用户</span><strong>{{overview.users||0}}</strong><small>全部账户</small></article><article class="fm-stat"><span class="label">接入站点</span><strong>{{overview.sites||0}}</strong><small>跨全部租户</small></article><article class="fm-stat"><span class="label">监听上游</span><strong>{{overview.sources||0}}</strong><small>{{overview.healthy_sources||0}} 个当前正常</small></article><article class="fm-stat"><span class="label">24 小时异常</span><strong>{{overview.alerts_24h||0}}</strong><small>{{overview.writes_24h||0}} 次同步成功</small></article></div>
        <section class="chart-card main-chart"><div class="chart-title"><div><span class="fm-kicker">14 天趋势</span><h2>运行事件走势</h2></div><span class="chart-note">按天聚合</span></div><AdminLineChart :data="overview.trend||[]"/></section>
        <div class="chart-grid"><section class="chart-card"><div class="chart-title"><div><span class="fm-kicker">平台结构</span><h2>上游平台占比</h2></div></div><AdminDonutChart :data="overview.platforms||[]"/></section><section class="chart-card"><div class="chart-title"><div><span class="fm-kicker">实时健康</span><h2>上游状态分布</h2></div></div><AdminDonutChart :data="overview.health||[]"/></section><section class="chart-card tenant-chart"><div class="chart-title"><div><span class="fm-kicker">租户规模</span><h2>站点与任务使用量</h2></div></div><AdminBarChart :data="overview.tenants||[]"/></section></div>
      </template>

      <template v-else-if="tab==='users'">
        <header class="admin-head"><div><span class="fm-kicker">账户与租户</span><h1>用户管理</h1><p>管理账户状态和权限，并查看每位用户的站点、上游、任务与异常数量。</p></div><FmButton variant="primary" @click="openCreateUser">新建用户</FmButton></header>
        <div class="user-toolbar"><form class="user-search" @submit.prevent="searchUsers"><label class="field"><span>搜索账户</span><input v-model.trim="query" placeholder="输入邮箱"/></label><FmButton variant="outline" type="submit">搜索</FmButton></form><span class="muted">共 {{userPage.total||0}} 位用户</span></div>
        <FmDataTable :columns="userColumns" :rows="userPage.items||[]" :loading="usersLoading" empty-text="没有符合条件的用户">
          <template #cell-email="{row}"><strong>{{row.email}}</strong><div class="muted">注册于 {{date(row.created_at)}}</div></template>
          <template #cell-role="{value}"><FmStatusPill :variant="value==='admin'?'info':'neutral'">{{value==='admin'?'管理员':'普通用户'}}</FmStatusPill></template>
          <template #cell-status="{value}"><FmStatusPill :variant="value==='active'?'ok':'error'">{{value==='active'?'正常':'已停用'}}</FmStatusPill></template>
          <template #cell-resources="{row}"><div class="resource-counts"><span>站点 <b>{{row.sites}}</b></span><span>上游 <b>{{row.sources}}</b></span><span>任务 <b>{{row.tasks}}</b></span><span>异常 <b>{{row.alerts}}</b></span></div></template>
          <template #actions="{row}"><FmButton variant="outline" @click="openEditUser(row)">编辑</FmButton><FmButton variant="ghost" :disabled="row.id===adminSession.user.id" @click="toggleUser(row)">{{row.id===adminSession.user.id?'当前账号':row.status==='active'?'停用':'启用'}}</FmButton><FmButton variant="danger" :disabled="row.id===adminSession.user.id" @click="removeUser(row)">删除</FmButton></template>
        </FmDataTable>
        <div class="pagination"><span>第 {{userPage.page||1}} / {{totalPages}} 页</span><div><FmButton variant="outline" :disabled="userPage.page<=1" @click="changePage(userPage.page-1)">上一页</FmButton><button v-for="page in visiblePages" :key="page" class="page-number" :class="{active:page===userPage.page}" @click="changePage(page)">{{page}}</button><FmButton variant="outline" :disabled="userPage.page>=totalPages" @click="changePage(userPage.page+1)">下一页</FmButton></div></div>
      </template>

      <template v-else>
        <header class="admin-head"><div><span class="fm-kicker">全站配置</span><h1>系统设置</h1><p>调度、注册、邮件和后台入口在这里统一管理。</p></div></header>
        <section class="settings-card"><form @submit.prevent="saveSettings"><div class="grid-2"><label class="field"><span>网站名称</span><input v-model.trim="settings.site_name" required/></label><label class="field"><span>管理后台访问路径</span><input v-model.trim="settings.admin_path" required pattern="[A-Za-z0-9_-]+"/><small>保存后访问 /{{settings.admin_path}}</small></label><label class="field"><span>网站外部地址</span><input v-model.trim="settings.public_url" type="url" placeholder="https://rate.example.com"/></label><label class="check admin-check"><input v-model="settings.registration_open" type="checkbox"/>允许新用户注册</label></div>
          <details class="advanced" open><summary>任务调度</summary><div class="advanced-body grid-2"><label class="field"><span>任务检查间隔（秒）</span><input v-model.number="settings.poll_seconds" type="number" min="10"/></label><label class="field"><span>New API 检查间隔（秒）</span><input v-model.number="settings.probe_seconds" type="number" min="10"/></label><label class="field"><span>模型清单检查（分钟）</span><input v-model.number="settings.model_check_minutes" type="number" min="1"/></label><label class="field"><span>邮件摘要间隔（分钟）</span><input v-model.number="settings.email_minutes" type="number" min="1"/></label></div></details>
          <details class="advanced"><summary>发件邮箱</summary><div class="advanced-body"><div class="grid-2"><label class="field"><span>SMTP 地址</span><input v-model.trim="settings.smtp_host"/></label><label class="field"><span>端口</span><input v-model.number="settings.smtp_port" type="number" min="1"/></label><label class="field"><span>账号</span><input v-model.trim="settings.smtp_user"/></label><label class="field"><span>发件人</span><input v-model.trim="settings.smtp_from" type="email"/></label></div><label class="field"><span>密码</span><input v-model="settings.smtp_password" type="password" :placeholder="settings.smtp_password_set?'已保存，留空表示不修改':'请输入 SMTP 密码'" autocomplete="new-password"/></label></div></details>
          <FmButton variant="primary" type="submit" :loading="savingSettings">保存系统设置</FmButton></form></section>
      </template>
    </main>
  </div>

  <FmModal v-model="userModal" :title="editingUser?'编辑用户':'新建用户'" kicker="账户管理" description="密码留空表示编辑时不修改现有密码。">
    <form id="admin-user-form" @submit.prevent="saveUser"><label class="field"><span>登录账号或邮箱</span><input v-model.trim="userForm.email" type="text" required/></label><label class="field"><span>{{editingUser?'新密码（可选）':'初始密码'}}</span><input v-model="userForm.password" type="password" :required="!editingUser" minlength="6"/></label><div class="grid-2"><label class="field"><span>账户权限</span><FmSelect v-model="userForm.role" aria-label="账户权限" :options="roleOptions"/></label><label class="field"><span>账户状态</span><FmSelect v-model="userForm.status" aria-label="账户状态" :options="statusOptions"/></label></div></form>
    <template #actions><FmButton variant="ghost" @click="userModal=false">取消</FmButton><FmButton variant="primary" type="submit" form="admin-user-form" :loading="userSaving">{{editingUser?'保存修改':'创建用户'}}</FmButton></template>
  </FmModal>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from"vue";import{useRoute,useRouter}from"vue-router";import{ChartNoAxesCombined,LogOut,Settings2,UsersRound}from"@lucide/vue";import{adminApi,adminLogout,adminSession,bootstrapAdmin,saveAdminSession,session,toast}from"../api/client.js";import AdminBarChart from"../components/AdminBarChart.vue";import AdminDonutChart from"../components/AdminDonutChart.vue";import AdminLineChart from"../components/AdminLineChart.vue";import FmButton from"../ui/freemodel/components/FmButton.vue";import FmDataTable from"../ui/freemodel/components/FmDataTable.vue";import FmModal from"../ui/freemodel/components/FmModal.vue";import FmSelect from"../ui/freemodel/components/FmSelect.vue";import FmStatePanel from"../ui/freemodel/components/FmStatePanel.vue";import FmStatusPill from"../ui/freemodel/components/FmStatusPill.vue";
const route=useRoute(),router=useRouter(),credentials=reactive({email:"",password:""}),loginBusy=ref(false),loginError=ref(""),tab=ref("overview"),loading=ref(false),demoBusy=ref(false),overview=ref({}),settings=reactive({}),savingSettings=ref(false),usersLoading=ref(false),userPage=ref({items:[],total:0,page:1,page_size:10}),query=ref(""),userModal=ref(false),editingUser=ref(null),userSaving=ref(false),userForm=reactive({email:"",password:"",role:"user",status:"active"}),nav=[{value:"overview",label:"数据中心",icon:ChartNoAxesCombined},{value:"users",label:"用户管理",icon:UsersRound},{value:"settings",label:"系统设置",icon:Settings2}],roleOptions=[{value:"user",label:"普通用户"},{value:"admin",label:"系统管理员"}],statusOptions=[{value:"active",label:"正常"},{value:"disabled",label:"停用"}],userColumns=[{key:"email",label:"账户"},{key:"role",label:"权限"},{key:"status",label:"状态"},{key:"resources",label:"租户资源统计"}],totalPages=computed(()=>Math.max(1,Math.ceil((userPage.value.total||0)/(userPage.value.page_size||10)))),visiblePages=computed(()=>{const current=userPage.value.page||1,start=Math.max(1,Math.min(current-2,totalPages.value-4)),end=Math.min(totalPages.value,start+4);return Array.from({length:end-start+1},(_,index)=>start+index)});
onMounted(async()=>{await bootstrapAdmin();if(adminSession.user)await loadAll()});
async function login(){loginBusy.value=true;loginError.value="";try{const data=await adminApi("/api/admin/auth/login",{method:"POST",body:JSON.stringify(credentials)});saveAdminSession(data);credentials.password="";toast("管理员登录成功","success");await loadAll()}catch(e){loginError.value=e.message;toast(e.message,"error")}finally{loginBusy.value=false}}
function logout(){adminLogout();toast("已退出管理后台");router.replace(`/${session.config.admin_path}`)}
async function loadAll(){loading.value=true;try{const[o,s]=await Promise.all([adminApi("/api/admin/overview"),adminApi("/api/admin/settings")]);overview.value=o;Object.assign(settings,s,{smtp_password:""});await loadUsers()}catch(e){toast(e.message,"error")}finally{loading.value=false}}
async function loadUsers(page=userPage.value.page||1){usersLoading.value=true;try{userPage.value=await adminApi(`/api/admin/users?page=${page}&page_size=10&query=${encodeURIComponent(query.value)}`)}catch(e){toast(e.message,"error")}finally{usersLoading.value=false}}
function searchUsers(){loadUsers(1)}function changePage(page){if(page>=1&&page<=totalPages.value)loadUsers(page)}
function openCreateUser(){editingUser.value=null;Object.assign(userForm,{email:"",password:"",role:"user",status:"active"});userModal.value=true}
function openEditUser(row){editingUser.value=row;Object.assign(userForm,{email:row.email,password:"",role:row.role,status:row.status});userModal.value=true}
async function saveUser(){userSaving.value=true;try{if(editingUser.value){await adminApi(`/api/admin/users/${editingUser.value.id}`,{method:"PUT",body:JSON.stringify(userForm)});toast("用户资料已更新","success")}else{await adminApi("/api/admin/users",{method:"POST",body:JSON.stringify(userForm)});toast("用户创建成功","success")}userModal.value=false;await Promise.all([loadUsers(editingUser.value?userPage.value.page:1),refreshOverview()])}catch(e){toast(e.message,"error")}finally{userSaving.value=false}}
async function toggleUser(row){try{await adminApi(`/api/admin/users/${row.id}`,{method:"PUT",body:JSON.stringify({email:row.email,password:"",role:row.role,status:row.status==='active'?'disabled':'active'})});toast(row.status==='active'?"用户已停用":"用户已启用","success");await loadUsers(userPage.value.page)}catch(e){toast(e.message,"error")}}
async function removeUser(row){if(!confirm(`确认删除用户“${row.email}”及其全部站点、上游、任务和日志？`))return;try{await adminApi(`/api/admin/users/${row.id}`,{method:"DELETE"});toast("用户及其租户数据已删除","success");await Promise.all([loadUsers(1),refreshOverview()])}catch(e){toast(e.message,"error")}}
async function refreshOverview(){overview.value=await adminApi("/api/admin/overview")}
async function createDemo(){demoBusy.value=true;try{const result=await adminApi("/api/admin/demo-data",{method:"POST"});toast(`${result.message}；可用 demo@ratewatch.local 登录查看`,"success");await Promise.all([refreshOverview(),loadUsers(1)])}catch(e){toast(e.message,"error")}finally{demoBusy.value=false}}
async function saveSettings(){savingSettings.value=true;try{const v=await adminApi("/api/admin/settings",{method:"PUT",body:JSON.stringify(settings)});Object.assign(settings,v,{smtp_password:""});session.config={...session.config,site_name:v.site_name,admin_path:v.admin_path,registration_open:v.registration_open};toast("系统设置已保存","success");if(route.params.adminPath!==v.admin_path)await router.replace(`/${v.admin_path}`)}catch(e){toast(e.message,"error")}finally{savingSettings.value=false}}
const date=value=>new Date(value).toLocaleString();
</script>
<style scoped>
