;overflow-wrap:anywhere}.admin-account button{display:flex;align-items:center;gap:7px;padding:0;background:transparent;color:#d5d6d3;text-align:left}.admin-shell>main{width:calc(100% - 228px);min-height:100vh;margin-left:228px;padding:38px 42px 80px}.admin-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:25px}.admin-head h1{margin:4px 0 0;font-size:27px}.admin-head p{margin:6px 0 0;color:var(--fm-ink-muted)}.chart-card,.settings-card{padding:22px 24px;border:1px solid var(--fm-line);border-radius:14px;background:var(--fm-bg-card)}.main-chart{margin-bottom:14px}.chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.tenant-chart{grid-column:1/-1}.chart-title{display:flex;align-items:start;justify-content:space-between;gap:12px;margin-bottom:18px}.chart-title h2{margin:4px 0 0;font-size:17px}.chart-note{padding:4px 7px;border-radius:6px;background:var(--fm-bg-warm);color:var(--fm-ink-muted);font-size:10px}.user-toolbar{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:14px}.user-search{display:flex;align-items:end;gap:8px}.user-search .field{width:min(340px,55vw);margin:0}.resource-counts{display:flex;gap:7px;flex-wrap:wrap}.resource-counts span{padding:4px 7px;border-radius:6px;background:var(--fm-bg-warm);color:var(--fm-ink-muted);font-size:10px}.resource-counts b{color:var(--fm-ink)}.pagination{display:flex;align-items:center;justify-content:space-between;margin-top:14px;color:var(--fm-ink-muted);font-size:11px}.pagination>div{display:flex;align-items:center;gap:7px}.page-number{display:grid;place-items:center;min-width:36px;height:36px;padding:0 10px;border:1px solid var(--fm-line);border-radius:9px;background:var(--fm-bg-card);color:var(--fm-ink-muted);font-size:12px;transition:all .16s}.page-number:hover{border-color:var(--fm-ink-muted);color:var(--fm-ink)}.page-number.active{border-color:var(--fm-ink);background:var(--fm-ink);color:var(--fm-bg);font-weight:600}.settings-card{max-width:960px}.admin-check{align-self:center;margin-top:10px}@media(max-width:900px){.admin-shell>aside{width:190px}.admin-shell>main{width:calc(100% - 190px);margin-left:190px;padding:28px 24px}.chart-grid{grid-template-columns:1fr}.tenant-chart{grid-column:auto}}@media(max-width:680px){.admin-auth{grid-template-columns:1fr;padding:18px}.admin-auth-copy{display:none}.admin-shell>aside{position:static;width:100%;padding:14px}.admin-brand{padding-bottom:12px}.admin-shell nav{grid-template-columns:repeat(3,1fr)}.admin-shell nav button{justify-content:center}.admin-account{display:none}.admin-shell>main{width:100%;margin:0;padding:22px 14px 60px}.admin-head,.user-toolbar{align-items:stretch;flex-direction:column}.admin-head .fm-actions>*{flex:1}.fm-stats{grid-template-columns:repeat(2,1fr)}.user-search{width:100%}.user-search .field{width:100%}.pagination{align-items:stretch;flex-direction:column}.pagination>div{flex-wrap:wrap}}
</style>
